"""Shared constants used by models, schemas, and validation.

Kept free of other app imports so config.py can use it without cycles.
"""

# Roles: admin (full access), researcher (read + edit), viewer (read only).
ROLES = ("admin", "researcher", "viewer")

ESTABLISHMENT_TYPES = ("restaurant", "fast_food", "food_manufacturer")

# Provenance label for establishments and WCO records.
#   synthetic   — generated by a script (e.g. the thesis demonstration dataset)
#   observed    — measured / reported by a participating establishment
#   unspecified — source not recorded (records created before this column existed)
DATA_SOURCES = ("synthetic", "observed", "unspecified")

# A negative weekly volume is always a data-entry error; the 10,000 L ceiling
# catches unit mix-ups (e.g. millilitres). Mirrored by a database CHECK.
MAX_WEEKLY_LITERS = 10_000.0
